roots = ['.', '../persistent/']
pats = ['*.json', '*.jsonl', '*.csv', '*.npy', '*.pkl', '*.parquet']
found = []
for r in roots:
    for pat in pats:
        for p in glob.glob(os.path.join(r, '**', pat), recursive=True):
            if 'quarantine' in p or '__pycache__' in p:
                continue
            found.append(p)
for p in sorted(found):
    try:
        mtime = datetime.datetime.fromtimestamp(os.path.getmtime(p)).isoformat()
    except:
        mtime = '?'
    print(f'{mtime}  {os.path.getsize(p):>10}  {p}')
" 2>/dev/null | head -40

